// 현장관리_빈칸 › 빈칸고르기: 노트북이 POST site-gaps (사장님 열쇠) 로 부른다 (카톡 '비서' 4단계, 10/31).
// 현장관리 백업(Airtable)에서 오늘~days 일 안에 시작하고 A(공동현관·세대 비번·화장실)·B(필름 번호) 중 빈칸이 있거나
// 아직 답을 못 받은 업체 확인 질문(checks)이 있는 현장만.
// 비번 같은 값은 돌려주지 않는다 (빈칸 이름만).
const body = $('빈칸요청').first().json.body || {};
const seoul = new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10);
const today = /^\d{4}-\d{2}-\d{2}$/.test(body.today || '') ? body.today : seoul;
const days = Math.min(Math.max(parseInt(body.days, 10) || 7, 0), 30);
const until = new Date(Date.parse(today + 'T00:00:00Z') + days * 864e5).toISOString().slice(0, 10);
const str = (v) => String(v == null ? '' : v).trim();
const clients = {};
for (const it of $('거래처읽기').all()) for (const r of (it.json.records || [])) {
  const f = r.fields || {};
  if (f.id) clients[f.id] = str(f['이름']);
}
// 업체 확인 질문 (2026-11-01) — 앱 설정(설정 표 data.checks). 앱에서 한 번도 안 고쳤으면 백업에 없으니 앱과 같은 기본 질문
const DEFAULT_CHECKS = [
  { id: 'door', text: '방문이 상하좌우 문틀에 닿는지 (닿으면 목수님 조정 부탁드려요)', ok: false },
  { id: 'overlap', text: '{날짜}에 겹치는 다른 공정', ok: false },
  { id: 'xmark', text: '현관문 부속교환할 부분에 마카펜으로 X 표시 부탁드려요', ok: true },
];
let checks = null;
for (const it of $('설정읽기').all()) for (const r of (it.json.records || [])) {
  try { const d = JSON.parse((r.fields || {}).data || '{}'); if (Array.isArray(d.checks)) checks = d.checks; } catch (e) { /* 다음 줄 */ }
}
checks = (checks || DEFAULT_CHECKS).filter((c) => c && str(c.id) && str(c.text) && !c.off).map((c) => ({ id: str(c.id), text: str(c.text), ok: !!c.ok }));
// 답을 받았거나 '이 현장은 안 물음'(skip, 11/1) 이면 묻지 않는다
const answered = (s, id) => { const a = (s.checks || {})[id]; return !!(a && typeof a === 'object' && a.skip) || !!str(a && typeof a === 'object' ? a.v : a); };
// 필름 주문 알림 (사장님 11/1) — 시공 orderDays(5)일 안이고 필름 단계가 아직 '필름 주문'(2) 전인 현장. 재고 없음·판매 중지까지 생각해 5일 전
const orderDays = Math.min(Math.max(parseInt(body.orderDays, 10) || 0, 0), 30);
const orderUntil = new Date(Date.parse(today + 'T00:00:00Z') + orderDays * 864e5).toISOString().slice(0, 10);
const last = until > orderUntil ? until : orderUntil;
// 주문 문자와 같은 모양 — 같은 번호는 한 번, 필요량은 ' + ' 로 (앱 Share.filmOrderText)
const orderFilms = (films) => {
  const seen = {}, order = [];
  (Array.isArray(films) ? films : []).filter((x) => x && str(x.code)).forEach((x) => {
    const k = str(x.code).replace(/\s+/g, ' ').toLowerCase();
    if (!seen[k]) { seen[k] = { code: str(x.code), qty: [] }; order.push(k); }
    if (str(x.qty) && !seen[k].qty.includes(str(x.qty))) seen[k].qty.push(str(x.qty));
  });
  return order.map((k) => ({ code: seen[k].code, qty: seen[k].qty.join(' + ') }));
};
const out = [], orders = [], filmChecks = [];
const tomorrow = new Date(Date.parse(today + 'T00:00:00Z') + 864e5).toISOString().slice(0, 10);
for (const it of $('현장읽기').all()) for (const r of (it.json.records || [])) {
  let s = {};
  try { s = JSON.parse((r.fields || {}).data || '{}'); } catch (e) { continue; }
  if (!s.id || s.hide) continue;
  const date = str(s.date).slice(0, 10);
  if (!date || date < today || date > last) continue;
  const name0 = str(s.name);
  const squash = (v) => v.replace(/\s+/g, '');
  const extra = [str(s.unit), str(s.size)].filter((v) => v && squash(name0).indexOf(squash(v)) === -1);
  const name = [name0].concat(extra).filter(Boolean).join(' ') || '(이름없음)';
  const client = clients[s.clientId] || clients[(r.fields || {})['거래처id']] || '';
  const stage = parseInt(s.filmStage, 10) || 0;
  if (orderDays && date <= orderUntil && stage < 2) orders.push({ id: s.id, client, name, date, stage, films: orderFilms(s.films) });
  // 🚚 업체가 필름을 가져다주는 현장 — 전날 그 방에 한 번 확인 (11/5). 이미 받았으면(수령) 안 물음
  if (s.filmVendor && date === tomorrow && stage < 3 && client) filmChecks.push({ id: s.id, client, name, date });
  if (date > until) continue;
  // 사장님 11/13: 모든 질문은 기본 '이 현장은 안 물음' — 앱에서 [묻기] 를 누른 것(askOn)만 묻는다
  const on = (k) => !!(s.askOn && s.askOn[k]);
  const missing = ['pwLobby', 'pwUnit', 'toilet'].filter((k) => !str(s[k]));
  if (!(Array.isArray(s.films) && s.films.some((x) => x && str(x.code)))) missing.push('films');
  for (let i = missing.length - 1; i >= 0; i--) if (!on(missing[i])) missing.splice(i, 1);
  const ask = checks.filter((c) => on(c.id) && !answered(s, c.id));
  // 📋 질문폼 링크 (11/13) — 노트북이 번호 질문 대신 이 링크를 보낸다
  const link = /^[a-z0-9]{12,40}$/.test(str(s.askKey)) ? 'https://jayunsu22.github.io/sitenote/ask.html#' + str(s.askKey) : '';
  // 📞 앱에서 '통화로 확인 — 그만 묻기' 를 누른 현장 (11/13) — 노트북이 묻지도 다시 묻지도 않는다
  if (str(s.askStop)) continue;
  if (!missing.length && !ask.length) continue;
  // 👤 개인고객 (11/5): 업체방이 없다 — '카톡 방 없음' 알림 대신 앱 현장 화면의 [문자로 물어보기]
  if (client.replace(/\s+/g, '') === '개인고객') continue;
  out.push({ id: s.id, client, name, date, missing, checks: ask, link });
}
const byDate = (a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
out.sort(byDate); orders.sort(byDate);
return [{ json: { today, until, sites: out, orders, filmChecks } }];

// 현장관리_빈칸 › 우편함넣기: 노트북이 POST site-fill (사장님 열쇠) — 업체 답에서 뽑은 칸 값을 우편함(staticData)에 둔다.
// 현장관리 앱이 site-fill-take 로 가져가 그 기기 현장 칸에 바로 넣는다 (원본이 기기에 있어서, 10/31 사장님 '우편함').
const body = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.fills = (sd.fills || []).filter((f) => now - f.t < 14 * 864e5);
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const FIELDS = ['pwLobby', 'pwUnit', 'toilet'];
// 📋 업무 내역 (11/4): 우편함에 들어온 일을 값 없이 적는다 — 업무내역 worklog.js 가 앱에 보여 준다
sd.worklog = sd.worklog || [];
const LABEL = { pwLobby: '공동현관 비번', pwUnit: '세대 비번', toilet: '화장실' };
const logOf = (o, f) => {
  const put = f.update ? ' 바꿈' : ' 넣음';
  if (o.kind === 'field') return { kind: 'site', title: LABEL[o.field] + put, detail: o.room };
  if (o.kind === 'films') return { kind: 'site', title: '필름 번호' + put, detail: o.room };
  if (o.kind === 'check') return { kind: 'site', title: '업체 확인 답 받음', detail: o.room };
  if (o.kind === 'filmOrdered') return { kind: 'crew', title: '필름 주문 문자', detail: o.room + (o.value ? ' · ' + o.value : '') };
  if (o.kind === 'crewAdd') return { kind: 'crew', title: o.name + ' 인원 넣음', detail: o.date };
  if (o.kind === 'task') return { kind: 'site', title: '할 일 추가', detail: o.title };
  if (o.kind === 'filmVendor') return { kind: 'site', title: '필름 업체가 가져옴으로 표시', detail: o.room };
  if (o.kind === 'done') return { kind: 'site', title: { pay: '잔금 받음', as: 'AS 완료', task: '할 일 완료' }[o.what], detail: '' };
  if (o.kind === 'undo') return { kind: 'site', title: { pay: '잔금 받음 취소', as: 'AS 완료 취소', task: '할 일 완료 취소', film: '필름 직접 주문 취소' }[o.what], detail: '결재함 되돌리기' };
  return null;
};
const srcOf = (o) => (o.room === '결재함' ? '결재함' : o.room === '인원 모집' ? '인원모집' : o.kind === 'filmOrdered' ? '필름 주문' : 'auto');
let n = 0;
for (const f of (Array.isArray(body.fills) ? body.fills : []).slice(0, 50)) {
  if (!f || typeof f !== 'object') continue;
  // 내역만 남기는 줄 — 앱 우편함에 넣지 않는다 (결재함 9시 실행 등, 11/4)
  if (f.kind === 'log') {
    if (s(f.title, 120)) sd.worklog.push({ id: 'l' + now.toString(36) + n, t: now, src: srcOf({ room: s(f.room, 40) }), kind: s(f.cat, 12) || 'crew', title: s(f.title, 120), detail: s(f.detail, 200), siteId: s(f.siteId, 40), state: f.state === 'need' ? 'need' : '', key: '' });
    n++;
    continue;
  }
  const o = { id: 'f' + now.toString(36) + n, t: now, siteId: s(f.siteId, 40), kind: f.kind, room: s(f.room, 40), at: s(f.at, 10) };
  if (!o.siteId) continue;
  if (o.kind === 'field') {
    o.field = FIELDS.includes(f.field) ? f.field : '';
    o.value = s(f.value, 300);
    if (!o.field || !o.value) continue;
  } else if (o.kind === 'films') {
    o.films = (Array.isArray(f.films) ? f.films : []).map((x) => ({ place: s(x && x.place, 40), code: s(x && x.code, 30) })).filter((x) => x.code).slice(0, 30);
    if (!o.films.length) continue;
  } else if (o.kind === 'check') {
    // 업체 확인 질문의 답 (2026-11-01)
    o.checkId = s(f.checkId, 40);
    o.value = s(f.value, 300);
    if (!o.checkId || !o.value) continue;
  } else if (o.kind === 'filmOrdered') {
    o.value = s(f.value, 300);   // 주문한 필름 'ps170 1롤 · px450 30m 이상'
  } else if (o.kind === 'crewAdd') {
    // 인원 모집 [넣기] (인원모집 흐름, 11/1) — 그날 인원에 이름
    o.date = s(f.date, 10); o.name = s(f.name, 20);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(o.date) || !o.name) continue;
  } else if (o.kind === 'task') {
    // 결재함 [내가할께] (업무일정표 흐름, 11/3) — 앱 할 일로. 현장과 상관없이 받는다 (siteId '-' 이면 현장 없음)
    o.title = s(f.title, 120); o.date = s(f.date, 10);
    if (!o.title || !/^\d{4}-\d{2}-\d{2}$/.test(o.date)) continue;
    if (f.vendor) o.vendor = true;   // 업체가 부탁한 일 (11/5)
  } else if (o.kind === 'filmVendor') {
    // 🚚 업체가 필름을 가져다줌 (11/5)
  } else if (o.kind === 'done') {
    // 결재함 [완료표시] (11/3): 잔금 받음·AS 완료·할 일 완료 → 앱 Kakao.fillPatch (11/4 고침: 전에는 여기서 버려져 앱에 안 들어갔다)
    o.what = ['pay', 'as', 'task'].includes(f.what) ? f.what : '';
    o.serviceId = s(f.serviceId, 60); o.taskId = s(f.taskId, 100);
    if (!o.what) continue;
  } else if (o.kind === 'undo') {
    // 결재함 [되돌리기] (11/5): 완료표시로 넣은 것을 앱에서 되돌린다 → 앱 Kakao.fillPatch
    o.what = ['pay', 'as', 'task', 'film'].includes(f.what) ? f.what : '';
    o.serviceId = s(f.serviceId, 60); o.taskId = s(f.taskId, 100);
    if (!o.what) continue;
  } else continue;   // 모르는 kind 는 버림. filmOrdered: 텔레그램 버튼으로 주문 문자를 보냄 → 앱 '필름 주문' 단계 (카톡_버튼, 11/1)
  sd.fills.push(o);
  const line = logOf(o, f);
  if (line) sd.worklog.push(Object.assign({ id: 'l' + now.toString(36) + n, t: now, src: srcOf(o), siteId: o.siteId === '-' ? '' : o.siteId, state: '', key: '' }, line));
  n++;
}
sd.worklog = sd.worklog.filter((x) => now - x.t < 90 * 864e5).slice(-2000);
return [{ json: { ok: true, n } }];

// 현장관리_빈칸 › 우편함꺼내기: 현장관리 앱이 POST site-fill-take (사장님 열쇠) {done:[번호]}.
// done 은 그 기기가 칸에 넣은 것 → 지운다. 남은 것을 모두 준다 (이 기기에 없는 현장은 앱이 건너뛰고 다른 기기를 기다린다). 14일 지나면 지움.
const body = $input.first().json.body || {};
const done = new Set((Array.isArray(body.done) ? body.done : []).map(String));
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.fills = (sd.fills || []).filter((f) => !done.has(f.id) && now - f.t < 14 * 864e5);
return [{ json: { fills: sd.fills.map((f) => Object.assign({}, f)) } }];

// 현장관리_빈칸 › 내역: 📋 업무 내역 (사장님 11/4: 진행 내역을 한곳에) — POST work-log (사장님 열쇠).
// 우편함에 들어오는 일(필름 주문·인원·잔금·칸 넣기)은 우편함넣기가 여기 sd.worklog 에 함께 적는다. 앱 비서·노트북 답장은 add 로.
// add { items: [{ id?, t?, src, kind, title, detail?, siteId?, state?, key? }] } / list {} → 최근 500 / resolve { id | key } → 확인함
// 비번 값은 적지 않는다. 90일 · 2000건까지. 설계 docs/superpowers/specs/2026-11-04-업무내역-design.md
const body = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const keep = () => { sd.worklog = (sd.worklog || []).filter((x) => now - x.t < 90 * 864e5).slice(-2000); };
keep();
if (body.action === 'add') {
  let n = 0;
  const has = new Set(sd.worklog.map((x) => x.id));
  for (const it of (Array.isArray(body.items) ? body.items : []).slice(0, 200)) {
    if (!it || !s(it.title, 120)) continue;
    const id = s(it.id, 60) || 'w' + now.toString(36) + n;
    if (has.has(id)) continue;   // 옮기기를 다시 해도 두 번 안 들어가게
    const t = Number(it.t) > 0 && Number(it.t) <= now ? Number(it.t) : now;
    sd.worklog.push({ id, t, src: s(it.src, 12) || 'me', kind: s(it.kind, 12) || 'etc', title: s(it.title, 120), detail: s(it.detail, 200),
      siteId: s(it.siteId, 40), state: it.state === 'need' ? 'need' : '', key: s(it.key, 60) });
    has.add(id);
    n++;
  }
  sd.worklog.sort((a, b) => a.t - b.t);
  keep();
  return [{ json: { ok: true, n } }];
}
// 🟢 노트북 신호 (11/5) — 노트북이 5분마다 보낸다. 끊기면 노트북확인(laptop.js)이 텔레그램으로
if (body.action === 'beat') { sd.beat = { at: now }; return [{ json: { ok: true } }]; }
// 🤖 비서 대화에 띄울 답장·처리 결과 (11/5) — 업체·고객 글 원문이 들어 있어 7일만 둔다. feed_add { items } / feed_list { after } → after 뒤 것
sd.feed = (sd.feed || []).filter((x) => now - x.t < 7 * 864e5).slice(-200);
if (body.action === 'feed_add') {
  (Array.isArray(body.items) ? body.items : []).slice(0, 20).forEach((it, i) => {
    if (!it) return;
    const list = (v) => (Array.isArray(v) ? v : []).map((x) => s(x, 160)).filter(Boolean).slice(0, 12);
    sd.feed.push({ id: s(it.id, 40) || 'f' + now.toString(36) + i, t: now, kind: s(it.kind, 8), from: s(it.from, 60), siteId: s(it.siteId, 40), siteName: s(it.siteName, 120), text: s(it.text, 600), lines: list(it.lines), left: list(it.left) });
  });
  return [{ json: { ok: true } }];
}
if (body.action === 'feed_list') {
  const after = Number(body.after) || 0;
  return [{ json: { ok: true, now, beat: (sd.beat && sd.beat.at) || 0, items: sd.feed.filter((x) => x.t > after) } }];
}
if (body.action === 'resolve') {
  const id = s(body.id, 60), key = s(body.key, 60);
  let n = 0;
  sd.worklog.forEach((x) => { if (x.state === 'need' && ((id && x.id === id) || (key && x.key === key))) { x.state = ''; n++; } });
  return [{ json: { ok: true, n } }];
}
return [{ json: { ok: true, items: sd.worklog.slice(-500).reverse().map((x) => ({ id: x.id, t: x.t, src: x.src, kind: x.kind, title: x.title, detail: x.detail, siteId: x.siteId, state: x.state })) } }];

// 현장관리_빈칸 › 노트북확인: 10분마다. 노트북 신호(worklog.js beat)가 30분 넘게 없으면 텔레그램 한 번, 돌아오면 한 번 (사장님 11/5)
// 밤(21시~8시)에는 안 깨운다 — 그때까지 멈춰 있으면 아침 8시에 알린다
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const hour = new Date(now + 9 * 3600e3).getUTCHours();
const at = (sd.beat && sd.beat.at) || 0;
if (!at) return [];
const late = now - at > 30 * 60e3;
if (late && !sd.beatDown && hour >= 8 && hour < 21) {
  sd.beatDown = now;
  return [{ json: { html: true, text: '🔴 <b>노트북이 멈춘 것 같아요</b>\n' + Math.round((now - at) / 60e3) + '분째 신호가 없습니다 — 카톡 읽기·보내기가 안 되고 있어요.\n노트북을 켜고 python reader.py 를 실행해 주세요.' } }];
}
if (!late && sd.beatDown) {
  delete sd.beatDown;
  return [{ json: { html: true, text: '🟢 <b>노트북이 다시 돌아왔어요</b>' } }];
}
return [];

// 현장관리_빈칸 › 정시보고: ⏰ 업무비서 정시 업무보고 (사장님 11/7: 매일 8시~17시 정시마다 지난 1시간 일을 폰 알림으로).
// 내역(sd.worklog)·답장(sd.feed)과 같은 저장 공간이라 이 흐름에 둔다. 두 길로 온다:
//  · 매시 정각 (정시 노드) — 한국 시간으로 설정한 시간(기본 8~17시)·요일이면 지난 1시간을 모아 비서 대화에 카드, 폰에 알림
//  · POST hourly-report (사장님 열쇠, 앱 🔔 설정): { action: 'sub', subscription } 이 폰 알림 받기 / 'unsub' { endpoint } /
//    'cfg' { cfg? } 설정 읽기·바꾸기 / 'test' 지금 지난 1시간으로 한 번 보내 보기
// → { resp, push: [{ subscription, title, message, url }] } — push 는 다음 노드가 Netlify send-push 로 보낸다 (견적 앱과 같은 VAPID).
// 설계 docs/superpowers/specs/2026-11-07-정시보고-design.md
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const APP = 'https://jayunsu22.github.io/sitenote/index.html#order';
sd.pushSubs = (sd.pushSubs || []).filter((x) => x && x.sub && x.sub.endpoint).slice(-5);
const DEF = { on: true, from: 8, to: 17, empty: false, sat: true, sun: false };
const cfg = Object.assign({}, DEF, sd.reportCfg || {});
let body = null;
try { body = $('보고요청').first().json.body || {}; } catch (e) { body = null; }   // 정각에 돌면 요청이 없다

// 한국 시간
const kst = (t) => new Date(t + 9 * 3600e3);
const hourName = (h) => (h < 12 ? '오전 ' + h : h === 12 ? '낮 12' : '오후 ' + (h - 12)) + '시';
const hm = (t) => { const d = kst(t); return d.getUTCHours() + ':' + String(d.getUTCMinutes()).padStart(2, '0'); };

function build(end) {
  const start = end - 3600e3;
  const inWin = (t) => t >= start && t < end;
  const log = (sd.worklog || []).filter((x) => inWin(x.t));
  const done = log.filter((x) => x.state !== 'need').map((x) => ({ t: x.t, title: s(x.title, 120), detail: s(x.detail, 120) }));
  const need = log.filter((x) => x.state === 'need').map((x) => ({ t: x.t, title: s(x.title, 120), detail: s(x.detail, 120) }));
  const replies = (sd.feed || []).filter((x) => inWin(x.t) && (x.kind === 'sms' || x.kind === 'kakao' || !x.kind) && x.from)
    .map((x) => ({ t: x.t, from: s(x.from, 40), site: s(x.siteName, 60), lines: (x.lines || []).slice(0, 4) }));
  const h = kst(end).getUTCHours(), ph = kst(start).getUTCHours();
  return { start, end, hour: h, title: '⏰ ' + hourName(h) + ' 업무보고 (' + ph + '시~' + h + '시)', done, need, replies, n: done.length + need.length + replies.length };
}
// 폰 알림 글 — 첫 줄 요약, 그 아래 항목 (펼치면 보인다)
function message(r) {
  const head = ['처리 ' + r.done.length + '건', '받은 답장 ' + r.replies.length + '건', r.need.length ? '확인 필요 ' + r.need.length + '건' : '확인 필요 없음'].join(' · ');
  const lines = r.done.slice(0, 3).map((x) => '✅ ' + x.title)
    .concat(r.replies.slice(0, 2).map((x) => '💬 ' + x.from + ' 답장' + (x.site ? ' · ' + x.site : '')))
    .concat(r.need.slice(0, 2).map((x) => '⚠️ ' + x.title));
  const more = r.n - lines.length;
  return [head].concat(lines, more > 0 ? ['… 외 ' + more + '건'] : []).join('\n');
}
// 비서 대화 카드 (알림함 feed — 앱이 30초마다 가져가 대화에 붙인다)
function feedItem(r, quiet) {
  sd.feed = sd.feed || [];
  const id = 'rep' + Math.floor(r.end / 3600e3);
  if (sd.feed.some((x) => x.id === id)) return;
  sd.feed.push({ id, t: now, kind: 'report', title: r.title, quiet: !!quiet, start: r.start, end: r.end,
    done: r.done.slice(0, 20), replies: r.replies.slice(0, 10), need: r.need.slice(0, 10) });
}
// ✈️ 사장님 11/13: 정시 업무보고는 텔레그램으로 (업무비서 앱 알림은 거래처 카톡·문자·일정 차지) — 카톡_알림 에 to:'tg'
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function tg(r) {
  return { to: 'tg', html: true, text: '<b>' + esc(r.title) + '</b>\n' + esc(message(r)) + '\n<a href="' + APP + '/log">업무 내역 전체</a>' };
}

if (body) {
  const act = s(body.action, 10);
  if (act === 'sub') {
    const sub = typeof body.subscription === 'string' ? JSON.parse(body.subscription) : body.subscription;
    if (!sub || !sub.endpoint) return [{ json: { resp: { ok: false, error: '구독 정보가 없음' }, push: [] } }];
    sd.pushSubs = sd.pushSubs.filter((x) => x.sub.endpoint !== sub.endpoint).concat([{ sub, at: now, device: s(body.device, 40) }]).slice(-5);
    return [{ json: { resp: { ok: true, n: sd.pushSubs.length, cfg }, push: [] } }];
  }
  if (act === 'unsub') {
    sd.pushSubs = sd.pushSubs.filter((x) => x.sub.endpoint !== s(body.endpoint, 1000));
    return [{ json: { resp: { ok: true, n: sd.pushSubs.length }, push: [] } }];
  }
  if (act === 'cfg') {
    if (body.cfg && typeof body.cfg === 'object') {
      const c = body.cfg, hr = (v, d) => Math.min(23, Math.max(0, Number.isFinite(+v) ? Math.round(+v) : d));
      sd.reportCfg = { on: c.on !== false, from: hr(c.from, cfg.from), to: hr(c.to, cfg.to), empty: !!c.empty, sat: c.sat !== false, sun: !!c.sun };
      if (sd.reportCfg.to < sd.reportCfg.from) sd.reportCfg.to = sd.reportCfg.from;
    }
    return [{ json: { resp: { ok: true, cfg: Object.assign({}, DEF, sd.reportCfg || {}), n: sd.pushSubs.length }, push: [] } }];
  }
  if (act === 'test') {
    // 정시 보고는 텔레그램으로 간다 (11/13) — 시험도 텔레그램, 이 폰이 등록돼 있으면 업무비서 앱 알림도 하나
    const r = build(now);
    const ping = { title: '🔔 시험 · 업무비서 알림', message: '이 폰으로 거래처 카톡·문자·일정 알림이 옵니다', url: APP, extra: { tag: 'test' } };
    return [{ json: { resp: { ok: true, n: r.n, subs: sd.pushSubs.length }, tg: tg(Object.assign({}, r, { title: '🔔 시험 · ' + r.title })),
      push: sd.pushSubs.map((x) => Object.assign({ subscription: x.sub }, ping)) } }];
  }
  // 📝 업무비서 알림 (11/13): 카톡_알림 이 거래처 카톡·문자·일정 알림을 넘긴다 { item: { title, text, buttons:[{text,data}], url, image } }
  // → 비서 대화 카드(feed kind 'notice', 버튼은 앱에서 누름) + 폰 알림 (버튼 앞 2개). 등록된 폰이 없으면 ok:false → 카톡_알림 이 텔레그램으로
  if (act === 'notify') {
    const it = body.item || {};
    const id = 'n' + now.toString(36) + Math.random().toString(36).slice(2, 6);
    const buttons = (Array.isArray(it.buttons) ? it.buttons : []).filter((b) => b && b.text && b.data).slice(0, 10).map((b) => ({ text: s(b.text, 30), data: s(b.data, 64) }));
    const title = s(it.title, 120) || '업무비서', text = s(it.text, 1500);
    const url = /^https:\/\/jayunsu22\.github\.io\/sitenote\//.test(s(it.url, 500)) ? s(it.url, 500) : APP;
    sd.feed = (sd.feed || []).concat([{ id, t: now, kind: 'notice', title, text, buttons, url }]).slice(-200);
    if (!sd.pushSubs.length) return [{ json: { resp: { ok: false, error: '등록된 폰 없음', id }, push: [] } }];
    const extra = { tag: id, actions: buttons.slice(0, 2).map((b, i) => ({ action: 'b' + i, title: b.text })),
      data: { id, buttons: buttons.slice(0, 2), text: text.slice(0, 500) } };
    if (/^https:\/\//.test(s(it.image, 500))) extra.image = s(it.image, 500);
    return [{ json: { resp: { ok: true, id, n: sd.pushSubs.length }, push: sd.pushSubs.map((x) => ({ subscription: x.sub, title, message: text.slice(0, 400), url, extra })) } }];
  }
  return [{ json: { resp: { ok: false, error: 'action 은 sub·unsub·cfg·test·notify' }, push: [] } }];
}

// 매시 정각 — 설정한 시간·요일만
const k = kst(now), h = k.getUTCHours(), dow = k.getUTCDay();
if (!cfg.on || h < cfg.from || h > cfg.to || (dow === 6 && !cfg.sat) || (dow === 0 && !cfg.sun)) return [{ json: { resp: { ok: true, skip: true }, push: [] } }];
const end = Math.floor(now / 3600e3) * 3600e3;   // 정각에 맞춤 (몇 초 늦게 돌아도 9:00~10:00)
const r = build(end);
if (!r.n) {
  feedItem(r, true);   // 대화에 회색 한 줄만
  return [{ json: Object.assign({ resp: { ok: true, empty: true }, push: [] }, cfg.empty ? { tg: tg(r) } : {}) }];
}
feedItem(r, false);
return [{ json: { resp: { ok: true, n: r.n }, push: [], tg: tg(r) } }];

// 현장관리_빈칸 › 질문폼: 📋 업체 확인 질문폼 (사장님 11/13: 업체 답이 너무 다양해 앱에 잘 안 들어간다 → 보기에서 고르기만).
// 업체가 카톡·문자 링크(sitenote/ask.html#열쇠)를 열면 GET ask-form?k=열쇠, [보내기] 면 POST ask-form { k, answers: { id: 값 } }.
// 열쇠 = 그 현장 전용 무작위 글자 (앱이 '묻기' 를 켤 때 site.askKey 로 만든다) — 로그인 없이 그 현장 질문만 보인다.
// 질문은 배포된 앱 share.js 의 askFormItems(현장, 설정) 그대로 (앱 화면과 늘 같게). 답은 이 흐름의 우편함(sd.fills)에 넣어 앱이 가져간다.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const req = (() => { try { return $('질문폼열기').isExecuted ? $('질문폼열기').first().json : $('질문폼보내기').first().json; } catch (e) { return {}; } })();
const post = (() => { try { return $('질문폼보내기').isExecuted; } catch (e) { return false; } })();
const key = s((post ? (req.body || {}).k : (req.query || {}).k), 40);
const COMPANY = '필름 시공팀';
const reply = (o) => [{ json: o }];
if (!/^[a-z0-9]{12,40}$/.test(key)) return reply({ ok: false, error: '주소가 잘못됨' });

// 그 열쇠의 현장 (현장읽기폼 이 FIND 로 좁혀 온 줄 중 열쇠가 정확히 같은 것)
let site = null;
for (const it of $('현장읽기폼').all()) for (const r of (it.json.records || [])) {
  try { const d = JSON.parse((r.fields || {}).data || '{}'); if (d && d.askKey === key && !d.hide) site = d; } catch (e) { /* 다음 줄 */ }
}
let settings = {};
for (const it of $('설정읽기폼').all()) for (const r of (it.json.records || [])) {
  try { const d = JSON.parse((r.fields || {}).data || '{}'); if (d && (Array.isArray(d.checks) || Array.isArray(d.toiletOpts))) settings = d; } catch (e) { /* 다음 줄 */ }
}
const today = new Date(now + 9 * 3600e3).toISOString().slice(0, 10);
// 시공일 다음 날까지만 연다 (시공 끝난 현장 링크는 닫음)
const closed = !site || !site.date || site.date < new Date(Date.parse(today + 'T00:00:00Z') - 864e5).toISOString().slice(0, 10);
if (!site) return reply({ ok: false, error: '없는 질문' });
if (closed) return reply({ ok: false, closed: true });

const Share = (function (module) { new Function('module', String($('앱코드받기폼').first().json.data || ''))(module); return module.exports; })({ exports: {} });
if (!Share || !Share.askFormItems) throw new Error('앱 share.js 를 못 읽음 (askFormItems 없음)');
sd.forms = sd.forms || {};
Object.keys(sd.forms).forEach((k) => { if (now - sd.forms[k].at > 21 * 864e5) delete sd.forms[k]; });
const sent = (sd.forms[key] || {}).ans || {};
// 업체가 이미 보냈지만 앱이 아직 안 가져간 답 — 폼에 '이미 보냄' 으로 다시 띄운다 (앱이 넣으면 질문에서 빠진다)
const items = Share.askFormItems(site, settings).map((q) => Object.assign({}, q, { sent: !!sent[q.id] }));
const days = ['일', '월', '화', '수', '목', '금', '토'];
const dateLabel = (() => { const d = new Date(site.date + 'T00:00:00Z'); return (d.getUTCMonth() + 1) + '/' + d.getUTCDate() + '(' + days[d.getUTCDay()] + ')'; })();
if (!post) return reply({ ok: true, company: COMPANY, site: { title: Share.titleLine(site), date: dateLabel }, items });

// 보내기 — 지금 묻는 질문의 답만 받는다
const answers = (req.body || {}).answers || {};
const byId = Object.fromEntries(items.map((q) => [q.id, q]));
const room = '질문폼';
sd.fills = (sd.fills || []).filter((f) => now - f.t < 14 * 864e5);
sd.worklog = sd.worklog || [];
const lines = [];
let n = 0;
const push = (o, title) => {
  sd.fills.push(Object.assign({ id: 'q' + now.toString(36) + n, t: now, siteId: site.id, room, at: today }, o));
  sd.worklog.push({ id: 'lq' + now.toString(36) + n, t: now, src: 'auto', kind: 'site', title, detail: Share.titleLine(site) + ' · 질문폼', siteId: site.id, state: '', key: '' });
  n++;
};
for (const id of Object.keys(answers).slice(0, 30)) {
  const q = byId[id];
  const v = s(answers[id], 300);
  if (!q || !v) continue;
  if (q.type === 'pw') {
    lines.push(q.label + ': ' + (/없음|당일/.test(v) ? v : '받음'));
    if (/당일/.test(v)) continue;   // 당일 알려준다 — 칸은 비워 둔다
    push({ kind: 'field', field: id, value: /^비번 없음/.test(v) ? '없음(열려 있음)' : v }, q.label + ' 넣음');
  } else if (id === 'toilet') {
    lines.push('화장실: ' + v);
    push({ kind: 'field', field: 'toilet', value: v }, '화장실 넣음');
  } else if (id === 'films') {
    // 한 줄에 '위치 번호' — 마지막 낱말을 번호로
    const films = v.split(/\n|,/).map((l) => l.trim()).filter(Boolean).slice(0, 20).map((l) => {
      const m = l.match(/^(.*\S)\s+(\S+)$/);
      return m ? { place: m[1].slice(0, 40), code: m[2].slice(0, 30) } : { place: '', code: l.slice(0, 30) };
    });
    lines.push('필름: ' + films.map((f) => (f.place ? f.place + ' ' : '') + f.code).join(', '));
    push({ kind: 'films', films }, '필름 번호 넣음');
  } else {
    lines.push(q.label.slice(0, 20) + ': ' + v);
    push({ kind: 'check', checkId: id, value: v }, '업체 확인 답 받음');
  }
}
if (!n && !lines.length) return reply({ ok: false, error: '고른 답이 없음' });
sd.forms[key] = { at: now, siteId: site.id, ans: Object.assign({}, sent, Object.fromEntries(Object.keys(answers).filter((k) => byId[k] && s(answers[k], 1)).map((k) => [k, true]))) };
sd.worklog = sd.worklog.filter((x) => now - x.t < 90 * 864e5).slice(-2000);
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const notify = { html: true, text: '📋 <b>업체가 질문폼으로 답함</b> · ' + esc(Share.titleLine(site)) + ' (' + lines.length + '/' + items.length + ')\n' + lines.map((l) => '· ' + esc(l)).join('\n') };
return reply({ ok: true, n, notify });
